"""Bind the immutable scientific release and authoritative candidate to the story."""
import hashlib,json,pathlib
root=pathlib.Path(__file__).resolve().parent.parent
names=['data/keystone-candidate.geojson','data/hydro.js','data/stations.geojson','data/mtbs-final-perimeters.geojson','data/forecast-round2.json','data/monitoring-glenwood.json','data/finance-evidence-ledger.json']
files={p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in names}
assert files[names[0]]=='dc5c013b6a94cc4844f080a4f25abbf46650adcab671a52775527c7e7c46cf91'
n=json.loads((root/names[4]).read_text());g=json.loads((root/names[5]).read_text())
a=n['allocation_metrics'];mae0=a[0]['owning_metrics']['mae_log1p_fnu'];mae1=a[1]['owning_metrics']['mae_log1p_fnu'];gain=100*(mae0-mae1)/mae0
assert round(gain,2)==6.84
assert [(r['true_positive_accepted'],r['accepted_alerts']) for r in g['allocation_metrics']]==[(6,8),(8,10)]
manifest={'schema_version':'1.0.0','release_date':'2026-11-13','purpose':'Immersive public presentation of existing frozen evidence; no new modeling or field collection','source_files_sha256':files,'chapters':[{'id':'polygon','geography':'Eagle County legacy candidate','source':names[0],'claim':'Actual county parcel boundary; historical screening candidate, no validated treatment rank'},{'id':'dependency','geography':'Eagle River region','source':names[1],'claim':'Retained NHDPlus HR cartographic network; conceptual dependency test is separate, no verified delivery edge'},{'id':'fire','geography':'Grand Lake North/East Inlet; separate case','source':[names[2],names[3]],'claim':'Final MTBS footprint, not progression or BAER soil severity; no hydrologic link to Eagle candidate'},{'id':'evidence','geography':'North/East Inlet','source':names[4],'north_relative_mae_log1p_gain_pct':gain,'claim':'North log-error improvement; monitoring promotion unsupported; East transfer failed'},{'id':'decision','geography':'Colorado River above Glenwood Springs, station 09071750; separate case','source':names[5],'claim':'Classifier 8 known high windows / 10 proposed slots versus baseline 6 / 8; accepted sets are not nested; joint promotion failed'},{'id':'next','geography':'Return to Eagle candidate','source':[names[0],names[6]],'claim':'Rights, delivery and treatment effect remain unverified; no funding, payout, credit or treatment-rank claim'}],'basemaps':{'parcel_close_view':{'service':'https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer','attribution':'USDA, USGS The National Map: Orthoimagery','meaning':'Current public imagery mosaic, not event-time imagery; no inferential use','metadata_checked_date':'2026-11-13','service_reported_refresh':'June 2024','service_reported_conus_naip_vintages':'2017-2021','tile_cache_maxzoom_used':16},'regional_context':{'style':'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json','attribution':'OpenStreetMap / CARTO; Terrarium elevation tiles','meaning':'Visual terrain and geographic context, no new terrain computation'}},'behavior':{'default':'Guided six-chapter story','old_scene_query':'Redirected to evidence.html, preserving query/hash','story_query':'chapter=polygon|dependency|fire|evidence|decision|next','geographic_transition':'Explicit camera cut from Eagle to Grand Lake and to Glenwood; no linking edge','reduced_motion':'Immediate camera cuts, no animated background','fallback':'Same local geometry and scene state in SVG; missing sources are not fabricated'},'scientific_data_changed':False}
(root/'data/story-evidence.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('Story evidence bound to',len(files),'retained public sources; six chapters; scientific outputs unchanged.')
